using System;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PlayerBoostEffect", menuName = "Data/Battle/Effects/Player Boost Effect")]
public class PlayerBoostEffect : Effect
{
	[Header("Player Boost")]
	[SerializeField]
	private string playerBoostDescriptionID;

	[Header("Purification")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private int purifyAmount;

	[SerializeField]
	private BattleActionAreaEnemyOmenLogic battleActionAreaEnemyOmenLogic;

	[NonSerialized]
	private int oldEffectAmount;

	protected override string GetLocalizedDescription()
	{
		return base.localizationManager.GetLocalizedString(playerBoostDescriptionID) + GetDieDiscardedDuringDrawPhasePurificationDescription();
	}

	public string GetDieDiscardedDuringDrawPhasePurificationDescription()
	{
		string arg = purifyAction.GetActionDescription(purifyAmount).UppercaseFirst().RemoveLastIfDotOrCommaAndIfNotJapaneseNorKoreanNorTraditionalChinese();
		return "\n" + Smart.Format(base.localizationManager.GetLocalizedForEach(), arg, base.localizationManager.GetLocalizedString("DieDiscardedDuringDrawPhase"));
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		oldEffectAmount = effectAmount;
		ReferenceSingleton<PlayerDiceHandHolder>.Instance.UpdateDrawDicesAmount(effectAmount);
		BoostGainedDuringStartOfTurnDiceDrawingUpdate(effectAmount);
	}

	private void BoostGainedDuringStartOfTurnDiceDrawingUpdate(int effectAmountToIncrease)
	{
		if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.DrawTurn)
		{
			ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().BoostGainedDuringStartOfTurnDiceDrawing += effectAmountToIncrease;
		}
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		int num = effectAmount - oldEffectAmount;
		ReferenceSingleton<PlayerDiceHandHolder>.Instance.UpdateDrawDicesAmount(num);
		oldEffectAmount = effectAmount;
		BoostGainedDuringStartOfTurnDiceDrawingUpdate(num);
	}

	public override void EffectDecreased(int effectAmount, GameObject effectOwner)
	{
		int amount = effectAmount - oldEffectAmount;
		ReferenceSingleton<PlayerDiceHandHolder>.Instance.UpdateDrawDicesAmount(amount);
		oldEffectAmount = effectAmount;
	}

	public void ActivatePlayerBoostPurification(int diceDiscardedAmount, GameObject effectOwner, bool removeBoost)
	{
		battleActionAreaEnemyOmenLogic.ActivateOmen(null, purifyAmount * diceDiscardedAmount, null, null);
		if (removeBoost)
		{
			effectOwner.GetComponent<UnitEffects>().RemoveEffect(this);
		}
	}
}
